function restoreDialog(id){if(job){toast('请先完成或取消流程演示。',true);return}const r=p().versions.find(x=>x.id===id),current=head().id;modal('恢复 '+id+' 的标注？','只恢复标注与图纸关联，当前和中间版本均保留。',`<div class="review-floor"><b>${esc(r.title)}</b><span>${stamp(r.created)}</span></div><p class="small muted" style="line-height:1.9;margin:15px 0">将创建 ${'r'+p().versions.length}，父版本为 ${current}，内容来自 ${id}。已有演示成果会标记为过期。不会删除、改写原始图片。</p><div class="notice">此处是本地原型版本管理，不表示获得建筑设计或交付审批。</div>`,`<button class="btn" data-close>取消</button><button class="btn primary" id="confirmRestore">恢复为新版本</button>`);$('confirmRestore').onclick=()=>{if(head().id!==current){toast('当前版本发生变化，请重新确认。',true);closeModal();return}closeModal();restore(id,'恢复 '+id+' 的标注')}}
function modal(title,sub,body,footer,wide=false){closePop();modalFocus=document.activeElement;$('modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-head"><div><h2 id="modalTitle">${esc(title)}</h2><p>${esc(sub)}</p></div><button class="iconbtn" data-close aria-label="关闭对话框">${ic('close')}</button></header><div class="modal-body">${body}</div><footer class="modal-footer">${footer}</footer></section></div>`;$('modalRoot').querySelectorAll('[data-close]').forEach(el=>el.onclick=closeModal);$('modalRoot').firstElementChild.onclick=e=>{if(e.target===e.currentTarget)closeModal()};$('modalRoot').querySelector('button')?.focus({preventScroll:true})}
function closeModal(){$('modalRoot').innerHTML='';if(modalFocus?.isConnected)modalFocus.focus({preventScroll:true});modalFocus=null}
function newProjectDialog(){if(state.projects.length>=limits.projects){toast('此原型最多保存 12 个项目。',true);return}modal('新建重建项目','先命名，进入工作台后再导入详细平面图。',`<div class="field"><label for="newProjectName">项目名称</label><input id="newProjectName" maxlength="80" placeholder="例如：发电厂运行辅助楼" autofocus></div><div class="notice">项目、图片、标注和版本保存在本浏览器。没有服务器上传。</div>`,`<button class="btn" data-close>取消</button><button class="btn primary" id="createProject">创建并进入</button>`);$('createProject').onclick=()=>{const name=$('newProjectName').value.trim();if(!name){$('newProjectName').focus();return}const pr=createProject(name);state.projects.unshift(pr);closeModal();saveSoon();enterProject(pr.id)};$('newProjectName').onkeydown=e=>{if(e.key==='Enter')$('createProject').click()};$('newProjectName').focus()}
function openSources(){guardDraft(()=>{if(job){toast('请先完成或取消流程演示，再管理图纸。',true);return}const fs=Object.entries(head().floors);modal('图纸与楼层','图片导入到新楼层；已存在的原图不覆盖。',`<button class="upload-zone" id="chooseImages" style="width:100%">${ic('upload')}<b>选择详细平面图</b><span>PNG / JPG / WebP · 可一次选择多张</span></button><div class="upload-list">${fs.map(([id,f])=>{const a=p().assets[f.assetId];return `<div class="upload-item"><img src="${a.url}" alt="${esc(f.label)}缩略图"><div><strong>${esc(a.name)}</strong><small>${a.width}×${a.height} px · ${a.sample?'演示楼层':'本地图片'}</small></div><input value="${esc(f.label)}" maxlength="10" aria-label="${esc(f.label)}楼层名称" data-floor-name="${id}"><button class="iconbtn" data-go-floor="${id}" aria-label="查看${esc(f.label)}">${ic('arrow')}</button></div>`}).join('')}</div><p class="tiny muted" style="margin-top:17px">P3 输入是详细平面图。当前原型仅支持图片文件；合并图板的楼层裁切、PDF 和真实尺度校准尚未接入。</p>`,`<button class="btn" data-close>关闭</button><button class="btn primary" id="saveFloorNames">保存楼层名称</button>`);$('chooseImages').onclick=()=>{uploadTarget=p().id;$('imageInput').click()};document.querySelectorAll('[data-go-floor]').forEach(el=>el.onclick=()=>{closeModal();switchFloor(el.dataset.goFloor)});$('saveFloorNames').onclick=()=>{const names=Object.fromEntries([...document.querySelectorAll('[data-floor-name]')].map(el=>[el.dataset.floorName,el.value.trim()]));if(Object.values(names).some(x=>!x)||new Set(Object.values(names)).size!==Object.values(names).length){toast('楼层名称不能为空或重复。',true);return}const changed=Object.entries(names).some(([id,n])=>head().floors[id].label!==n);closeModal();if(changed){commit('更新楼层名称',floors=>{for(const [id,n] of Object.entries(names))floors[id].label=n});toast('楼层名称已保存。')}else toast('楼层名称未变化。')}})}
async function upload(files){const pr=p();if(!pr||job||!files?.length)return;const pid=pr.id;if(Object.keys(head(pr).floors).length+files.length>limits.floors){toast('每个项目最多 12 张楼层图片。',true);return}try{const assets=[];for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>limits.file)throw new Error('请使用 12 MB 以内 PNG / JPG / WebP 图片。');const url=await new Promise((res,rej)=>{const rd=new FileReader();rd.onload=()=>res(rd.result);rd.onerror=rej;rd.readAsDataURL(file)});const im=await img(url);if(im.naturalWidth*im.naturalHeight>limits.pixels)throw new Error('单张图片最多 1200 万像素。');assets.push({id:uid('asset'),name:file.name,url,width:im.naturalWidth,height:im.naturalHeight,sample:false,provenance:'用户本地导入；未识图、未校尺'})}if(activeId!==pid||job)throw new Error('项目或任务状态已变化，请重新导入。');let first;for(const a of assets)pr.assets[a.id]=a;const success=commit('导入 '+assets.length+' 张平面图',floors=>{let k=Object.keys(floors).length+1;for(const a of assets){while(floors['F'+String(k).padStart(2,'0')])k++;const fid='F'+String(k).padStart(2,'0');if(!first)first=fid;floors[fid]={label:k+'F',name:'楼层待确认',assetId:a.id,items:[]};k++}});if(!success){assets.forEach(a=>delete pr.assets[a.id]);return}closeModal();activeFloor=first;pr.currentFloor=first;await loadFloor(true);event(pr,'sources.imported','本地导入图片',{count:assets.length,uploadedToServer:false,recognized:false});toast('图片已载入。没有自动套用示例识别框，可直接拉框补充。')}catch(e){toast(e.message||'图片导入失败',true)}}
function recognize(){if(!asset())return;if(job){renderTask();return}guardDraft(()=>{if(!asset().sample){modal('识别模型尚未接入','你的图片不会被套上示例检测结果。',`<div class="notice">当前已完成本地原图导入。可使用拉框工具记录遗漏对象；自动识图需要后续接入视觉模型。</div>`,`<button class="btn" data-close>关闭</button><button class="btn primary" id="manualInstead">先手工标注</button>`);$('manualInstead').onclick=()=>{closeModal();setTool('rect')};return}modal('载入这一层的识别演示','使用手工预设候选，不调用模型。',`<p class="small muted" style="line-height:1.9">重新载入当前 ${esc(floor().label)} 的候选框。人工补充和已确认的对象保留，已有未确认候选按示例补齐。其他楼层不变。</p>`,`<button class="btn" data-close>取消</button><button class="btn primary" id="startRecognize">开始识别演示</button>`);$('startRecognize').onclick=()=>{closeModal();startJob('recognition')}})}
function preflight(){if(job){taskExpanded=true;renderTask();return}if(!asset())return;guardDraft(()=>{const pending=allItems().filter(o=>o.status==='pending').length;const base=head().id;const realCount=Object.values(head().floors).filter(f=>!p().assets[f.assetId].sample).length;modal('生成之前，确认这一版','基于当前原图与补充标注冻结演示快照。',`<div class="review-floors">${Object.values(head().floors).map(f=>`<div class="review-floor"><b>${esc(f.label)} · ${esc(f.name)}</b><span>${f.items.length} 个框 / 人工补充 ${f.items.filter(o=>o.source==='manual').length}</span></div>`).join('')}</div>${pending?`<div class="notice amber" style="margin-bottom:12px">还有 ${pending} 处待复核对象。可以返回图上确认；继续演示的结果会明确标为“待复核”，不自动批准。</div>`:''}<div class="notice">本次仅演示几何构建、二维/三维导出和校验的交互阶段。不会生成实际 DXF / PDF / GLB，不调用模型或 BIMFACE。${realCount?'导入的真实图片不会被冒充为已重建三维。':''}</div><label class="form-check"><input id="demoConsent" type="checkbox"><span>我了解这是流程演示，基于 ${base} 继续；不表示批准真实建筑方案。</span></label>`,`<button class="btn" id="returnReview">返回复核</button><button class="btn primary" id="startGeneration" disabled>${ic('spark')}开始流程演示</button>`);$('demoConsent').onchange=()=>{$('startGeneration').disabled=!$('demoConsent').checked};$('returnReview').onclick=()=>{closeModal();openDrawer('issues')};$('startGeneration').onclick=()=>{if(head().id!==base){toast('当前版本变化，请重新确认。',true);closeModal();return}closeModal();closeDrawer();startJob('generation')}})}
